Here’s the JavaScript equivalent of your Go function:

```js
function CorrectBracketing(brackets) {
    const stack = [];

    for (const c of brackets) {
        switch (c) {
            case '(':
            case '[':
            case '{':
                stack.push(c);
                break;

            case ')':
            case ']':
            case '}':
                if (stack.length === 0) {
                    return false;
                }

                const lastBracket = stack.pop();

                if (
                    (c === ')' && lastBracket !== '(') ||
                    (c === ']' && lastBracket !== '[') ||
                    (c === '}' && lastBracket !== '{')
                ) {
                    return false;
                }
                break;

            default:
                // Ignore non-bracket characters
        }
    }

    return stack.length === 0;
}
```

### Notes

- `for (const c of brackets)` iterates over characters similarly to Go’s `for _, c := range brackets`.
- `stack.push(c)` replaces Go’s `append(stack, c)`.
- `stack.pop()` replaces the Go pop logic.
- `stack.length === 0` checks whether the stack is empty.

### Example usage

```js
console.log(CorrectBracketing("{[()]}")); // true
console.log(CorrectBracketing("([)]"));   // false
console.log(CorrectBracketing("()[]{}abc")); // true
console.log(CorrectBracketing("(("));      // false
console.log(CorrectBracketing(")"));      // false
```

