  let result = 1n;

  for (const number of iterable) {
    result *= number;
  }

  return result;
}

function numsManipulationBig(n) {
  const digits = String(n)
    .split('')
    .filter(ch => ch >= '0' && ch <= '9')
    .map(Number);

  const evens = digits.filter(x => x % 2 === 0);
  const odds = digits.filter(x => x % 2 !== 0);

  if (evens.length > 0 && odds.length > 0) {
    const evenComp = evens.reduce(
      (sum, x) => sum + BigInt(x) ** 2n,
      0n
    );

    let oddComp = 1n;

    for (const o of odds) {
      oddComp *= BigInt(o) ** 3n;
    }

    return evenComp + oddComp;
  } else if (evens.length > 0) {
    const half = Math.floor(evens.length / 2);
    const firstHalf = evens.slice(0, half);

    return prodBig(firstHalf.map(x => BigInt(x) ** 3n));
  } else {
    const half = Math.floor(odds.length / 2);
    const firstHalf = odds.slice(0, half);

    return firstHalf.reduce(
      (sum, x) => sum + BigInt(x) ** 2n,
      0n
    );
  }
}
```

