      executed.push({step: step.name, result});
      await this.updateJournal(id, 'executed', [...executed]);
   }
   await this.updateJournal(id, 'completed');
   return {status:'completed'};
 } catch (err) {
   for (let i=executed.length-1;i>=0;i--) await step.compensate?.(ctx);
   await this.updateJournal(id, 'failed', err.message);
