Here is a complete implementation of a circular linked list with a dummy node in C. 

A **dummy node** (also called a sentinel node) is a node that does not hold any actual data but acts as the permanent head of the list. This simplifies operations because there is always a "head" to reference, eliminating edge cases related to empty lists and pointer manipulation when the list becomes empty.

### C Implementation

```c
#include <stdio.h>
#include <stdlib.h>

// Node structure
typedef struct Node {
    int data;
    struct Node *next;
} Node;

// List structure containing the dummy node
typedef struct {
    Node *dummy;
} CircularList;

// Initialize the circular linked list with a dummy node
void initList(CircularList *list) {
    list->dummy = (Node *)malloc(sizeof(Node));
    list->dummy->data = 0; // Dummy nodes don't store real data
    list->dummy->next = list->dummy; // Point to itself for an empty list
}

// Function to get the size of the list
int getSize(CircularList *list) {
    if (list->dummy->next == list->dummy) return 0;

    int count = 0;
    Node *curr = list->dummy->next;
    while (curr != list->dummy) {
        count++;
        curr = curr->next;
    }
    return count;
}

// 1. Add element at the BEGINNING
void addBeginning(CircularList *list, int data) {
    Node *newNode = (Node *)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = list->dummy->next;       // Point to the old first node
    list->dummy->next = newNode;            // Dummy now points to the new first node
}

// 2. Add element at the MIDDLE
void addMiddle(CircularList *list, int data) {
    int size = getSize(list);

    // If list is empty, just add at the beginning
    if (size == 0) {
        addBeginning(list, data);
        return;
    }

    // Calculate the middle position (0-indexed). 
    // For size 4, mid is 2. For size 5, mid is 2.
    int mid = size / 2;

    Node *curr = list->dummy;
    // Traverse to the node just BEFORE the middle position
    for (int i = 0; i < mid; i++) {
        curr = curr->next;
    }

    Node *newNode = (Node *)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = curr->next;       // Insert between curr and curr->next
    curr->next = newNode;
}

// 3. Add element at the END
void addEnd(CircularList *list, int data) {
    Node *newNode = (Node *)malloc(sizeof(Node));
    newNode->data = data;

    // If list is empty, just add at the beginning
    if (list->dummy->next == list->dummy) {
        addBeginning(list, data);
        return;
    }

    // Traverse to the last node (the node before the dummy)
    Node *curr = list->dummy->next;
    while (curr->next != list->dummy) {
        curr = curr->next;
    }

    curr->next = newNode;       // Last node points to new node
    newNode->next = list->dummy; // New node points back to dummy
}

// 4. Search for an element
Node* search(CircularList *list, int data) {
    if (list->dummy->next == list->dummy) return NULL; // Empty list

    Node *curr = list->dummy->next;
    while (curr != list->dummy) {
        if (curr->data == data) {
            return curr; // Found
        }
        curr = curr->next;
    }
    return NULL; // Not found
}

// 5. Remove an element by value
int remove(CircularList *list, int data) {
    if (list->dummy->next == list->dummy) return 0; // Empty list

    Node *curr = list->dummy;

    // Traverse to find the node PREVIOUS to the node with the target data
    while (curr->next != list->dummy) {
        if (curr->next->data == data) {
            Node *toRemove = curr->next;
            curr->next = toRemove->next; // Bypass the node to remove
            free(toRemove);              // Free memory
            return 1; // Successfully removed
        }
        curr = curr->next;
    }
    return 0; // Element not found
}

// Helper function to display the list
void display(CircularList *list) {
    if (list->dummy->next == list->dummy) {
        printf("List is empty.\n");
        return;
    }

